import Foundation
struct MessageDocument: Equatable { enum Node: Equatable { case heading(Int, String), paragraph(String), quote(String), list(String), code(String, String), table([String]), displayMath(String) }; var nodes: [Node] }
struct MessageDocumentParser {
 func parse(_ source: String) -> MessageDocument { var nodes:[MessageDocument.Node] = []; var paragraph:[String] = []; var code:[String] = []; var language = "plain"; var fenced = false
  func flush() { if !paragraph.isEmpty { nodes.append(.paragraph(paragraph.joined(separator:"\n"))); paragraph=[] } }
  for line in source.components(separatedBy: .newlines) { if line.hasPrefix("```") { flush(); if fenced { nodes.append(.code(language, code.joined(separator:"\n"))); code=[] } else { language=String(line.dropFirst(3)).nilIfBlank ?? "plain" }; fenced.toggle(); continue }; if fenced { code.append(line); continue }; if line.hasPrefix("$$"), line.hasSuffix("$$"), line.count > 4 { flush(); nodes.append(.displayMath(String(line.dropFirst(2).dropLast(2)))); continue }; if line.hasPrefix("#") { flush(); let count=line.prefix(while:{$0 == "#"}).count; nodes.append(.heading(count,String(line.dropFirst(count)).trimmingCharacters(in:.whitespaces))); continue }; if line.hasPrefix("> ") { flush(); nodes.append(.quote(String(line.dropFirst(2)))); continue }; if line.hasPrefix("- ") || line.hasPrefix("* ") { flush(); nodes.append(.list(String(line.dropFirst(2)))); continue }; if line.contains("|") && !line.trimmingCharacters(in:.whitespaces).hasPrefix("|---") { flush(); nodes.append(.table(line.split(separator:"|").map { String($0).trimmingCharacters(in:.whitespaces) })); continue }; if line.isEmpty { flush() } else { paragraph.append(line) } }; flush(); if fenced { nodes.append(.paragraph("```\(language)\n\(code.joined(separator:"\n"))")) }; return .init(nodes:nodes) }
}
private extension String { var nilIfBlank:String? { isEmpty ? nil : self } }
